import {
  SecurityDomainProjection,
  SecurityDomainFilter,
} from 'app/features/access/security-domain/model/security-domain.model';
import { FormControl } from '@angular/forms';
import { SecurityDomainRepository } from 'app/features/access/security-domain/repository/security-domain-repository.service';
import { Shift } from '@common/data/repository/repository.model';
import { input, effect, Component } from '@angular/core';

@Component({
  selector: 'security-domain-view-list',
  templateUrl: './security-domain-view-list.component.html',
  styleUrls: ['./security-domain-view-list.component.scss'],
  standalone: false,
})
export class SecurityDomainViewListComponent {
  filters = input<SecurityDomainFilter>();
  actionName = input<string>('security-domain');
  fixed = input<{ [key: string]: any }>();
  hidden = input<{ [key: string]: any }>();
  search = new FormControl<any>(undefined);
  list: Shift<SecurityDomainProjection[], SecurityDomainFilter>;

  constructor(repository: SecurityDomainRepository) {
    this.list = repository.projections(['tenant']);
    effect(() => {
      setTimeout(() => this.makeSearch());
    });
  }
  makeSearch() {
    const result = { limit: 10 } as any;
    const filter = this.search.value;
    const external = this.filters();
    if (external?.search) {
      result.search = external.search;
    }
    if (external?.enabled) {
      result.enabled = external.enabled;
    }
    if (external?.name) {
      result.name = external.name;
    }
    if (external?.tenants) {
      result.tenants = external.tenants;
    }
    if (filter?.search) {
      result.search = filter.search;
    }
    if (filter?.enabled) {
      result.enabled = filter.enabled;
    }
    if (filter?.name) {
      result.name = filter.name;
    }
    if (filter?.tenants?.$ref) {
      result.tenants = filter.tenants.$ref;
    }
    if (filter?.order) {
      result.order = filter.order;
    }
    this.list.fetch(result);
  }

  next() {
    this.list.next();
  }

  reload() {
    this.list.reset();
  }

  prev() {
    console.log('PREV');
  }
}
